class Solution {
public:
    string alphabetBoardPath(string target) {
        string res = "";
        int r = 0, c = 0;
        for (char ch : target) {
            int idx = ch - 'a';
            int tr = idx / 5, tc = idx % 5;
            if (tc < c) res.append(c - tc, 'L');
            if (tr < r) res.append(r - tr, 'U');
            if (tr > r) res.append(tr - r, 'D');
            if (tc > c) res.append(tc - c, 'R');
            res.push_back('!');
            r = tr;
            c = tc;
        }
        return res;
    }
};

class Solution {
    public String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int r = 0, c = 0;
        for (char ch : target.toCharArray()) {
            int idx = ch - 'a';
            int tr = idx / 5, tc = idx % 5;
            while (tc < c) { sb.append('L'); c--; }
            while (tr < r) { sb.append('U'); r--; }
            while (tr > r) { sb.append('D'); r++; }
            while (tc > c) { sb.append('R'); c++; }
            sb.append('!');
        }
        return sb.toString();
    }
}

var alphabetBoardPath = function(target) {
    const res = [];
    let r = 0, c = 0;
    for (const ch of target) {
        const idx = ch.charCodeAt(0) - 97;
        const tr = Math.floor(idx / 5), tc = idx % 5;
        if (tc < c) res.push('L'.repeat(c - tc));
        if (tr < r) res.push('U'.repeat(r - tr));
        if (tr > r) res.push('D'.repeat(tr - r));
        if (tc > c) res.push('R'.repeat(tc - c));
        res.push('!');
        r = tr;
        c = tc;
    }
    return res.join('');
};
